const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('/app/index.html', 'utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
if (!m) { console.error('FAIL: no inline script found'); process.exit(1); }
const script = m[1];

function makeGradient() { return { addColorStop() {} }; }
function makeCtx() {
  return {
    fillStyle: '', strokeStyle: '', lineWidth: 1, lineCap: 'butt', globalAlpha: 1,
    globalCompositeOperation: 'source-over', filter: 'none',
    setTransform() {}, save() {}, restore() {}, translate() {}, rotate() {}, scale() {},
    beginPath() {}, closePath() {}, ellipse() {}, arc() {}, rect() {},
    moveTo() {}, lineTo() {}, bezierCurveTo() {}, quadraticCurveTo() {},
    fill() {}, stroke() {}, clip() {}, fillRect() {},
    createRadialGradient: makeGradient, createLinearGradient: makeGradient,
  };
}
let rafCb = null, rafCount = 0;
const canvas = {
  width: 0, height: 0, style: {},
  getContext: () => makeCtx(),
};
const listeners = {};
const sandbox = {
  console,
  performance: { now: () => 1000 + rafCount * 16 },
  requestAnimationFrame: (cb) => { rafCb = cb; rafCount++; return rafCount; },
  cancelAnimationFrame: () => { rafCb = null; },
  Math, JSON,
  location: { reload() {} },
  document: {
    hidden: false,
    getElementById: (id) => (id === 'scene' ? canvas : null),
    addEventListener: (ev, fn) => { (listeners['doc:' + ev] ||= []).push(fn); },
  },
  window: null, // set below
};
sandbox.window = {
  innerWidth: 900, innerHeight: 700, devicePixelRatio: 1,
  matchMedia: (q) => ({
    matches: false, media: q,
    addEventListener() {}, addListener() {},
  }),
  addEventListener: (ev, fn) => { (listeners['win:' + ev] ||= []).push(fn); },
};
sandbox.window.window = sandbox.window;
sandbox.globalThis = sandbox;
vm.createContext(sandbox);
// Keep window props accessible as bare globals used by the script (innerWidth not used bare; matchMedia via window)
try {
  vm.runInContext(script, sandbox, { filename: 'inline-script.js' });
  console.log('init: OK (script executed without throwing)');
} catch (e) {
  console.error('FAIL init threw:', e && e.stack || e);
  process.exit(1);
}
if (!rafCb) { console.error('FAIL: no requestAnimationFrame callback was queued'); process.exit(1); }
// Drive several frames through the real loop (init + update/render path)
try {
  for (let i = 0; i < 6; i++) {
    const cb = rafCb; rafCb = null;
    cb(1000 + i * 100);
    if (!rafCb && i < 5) throw new Error('loop stopped queuing frames at frame ' + i);
  }
  console.log('frames: OK (6 animation frames rendered, loop still queuing)');
} catch (e) {
  console.error('FAIL during frames:', e && e.stack || e);
  process.exit(1);
}
// Exercise the pointer interaction path
try {
  const mv = (listeners['win:pointermove'] || [])[0];
  if (mv) { mv({ clientX: 600, clientY: 300, pointerType: 'mouse' }); mv({ clientX: 450, clientY: 360, pointerType: 'mouse' }); }
  const dn = (listeners['win:pointerdown'] || [])[0];
  if (dn) dn({ clientX: 450, clientY: 360 });
  const cb = rafCb; rafCb = null; if (cb) cb(2000);
  console.log('interaction: OK (pointermove + pointerdown + extra frame, no throw)');
} catch (e) {
  console.error('FAIL interaction:', e && e.stack || e);
  process.exit(1);
}
// Reduced-motion path: re-run with matches=true and confirm it renders once without looping
const sandbox2 = { ...sandbox };
sandbox2.window = { ...sandbox.window, matchMedia: (q) => ({ matches: true, media: q, addEventListener() {} }) };
sandbox2.window.window = sandbox2.window;
let raf2 = null;
sandbox2.requestAnimationFrame = (cb) => { raf2 = cb; return 1; };
sandbox2.document = { hidden: false, getElementById: () => ({ width:0, height:0, getContext: () => makeCtx() }), addEventListener() {} };
sandbox2.globalThis = sandbox2;
vm.createContext(sandbox2);
try {
  vm.runInContext(script, sandbox2, { filename: 'inline-script-reduced.js' });
  console.log('reduced-motion: OK (static render, rafQueued=' + (raf2 !== null) + ')');
  if (raf2 !== null) { console.error('FAIL: reduced-motion should not start the animation loop'); process.exit(1); }
} catch (e) {
  console.error('FAIL reduced-motion:', e && e.stack || e);
  process.exit(1);
}
console.log('SMOKE PASS');

